// Bundles the webview script: the shared cat art (src/catArt.ts, compiled as CommonJS) is wrapped
// into a global `CatArt` object and prepended to the compiled webview script, producing a single
// classic script at out/webview/cats.js (no module loader needed in the webview).
const fs = require('fs');
const path = require('path');

const out = path.resolve(__dirname, '..', 'out');
const art = fs.readFileSync(path.join(out, '.webview', 'catArt.js'), 'utf8').replace(/^\/\/# sourceMappingURL=.*$/m, '');
const styles = fs.readFileSync(path.join(out, '.webview', 'catStyles.js'), 'utf8').replace(/^\/\/# sourceMappingURL=.*$/m, '');
const cats = fs.readFileSync(path.join(out, '.webview', 'webview', 'cats.js'), 'utf8');
const bundle =
  '/* Generated by scripts/bundle-webview.js: src/catArt.ts + src/catStyles.ts + src/webview/cats.ts */\n' +
  'var CatArt = (function () {\n  var exports = {};\n' +
  art +
  '\n  return exports;\n})();\n' +
  'var CatStyles = (function () {\n  var exports = {};\n' +
  styles +
  '\n  return exports;\n})();\n' +
  cats;
fs.mkdirSync(path.join(out, 'webview'), { recursive: true });
fs.writeFileSync(path.join(out, 'webview', 'cats.js'), bundle);
